		}


	}

function changeM(t){
	const {java,book} = this;
	let type;
    let bookintro = String(book.intro);
	if(t == 0){
		type = /视 频/.test(this.Map("模式"))?"🎧 音 频":"🎥 视 频";
		type = /视频模式/.test(book.intro)?"🎧 音 频":"🎥 视 频";
		this.setHeaders("模式="+type);
    }else if(t==1){
			type = /视频/.test(this.Map("UP主"))?"📖 显示专栏":"🎬 显示视频";
			type = /显示视频/.test(bookintro)?"📖 显示专栏":"🎬 显示视频";
			this.setHeaders("UP主="+type);
		}
	java.refreshBookInfo()
	}


function showCom(bu){
	const {java,book,cache,chapter,source} = this;
    let hotu,newu,name = "";
    let bu = book?String(book.tocUrl):"";

	if(/v1\/detail/.test(bu)){
         hotu = this.getReply(bu.match(/id=(\d+)/)[1], 17, 3);
         newu = this.getReply(bu.match(/id=(\d+)/)[1], 17, 2);
    }else if(/article\/view/.test(bu)){
         hotu = this.getReply(bu.match(/\?id=(\d+)/)[1], 12, 3)
         newu = this.getReply(bu.match(/id=(\d+)/)[1], 12, 2);
    }else if(/opus\/detail/.test(bu)){
         hotu = this.getReply(book.getVariable("id"), 11, 3)
         newu = this.getReply(bu.match(/id=(\d+)/)[1], 11, 2);
    }else if(!/acc\/info/.test(bu)) {
        let aid = cache.get("comaid") || bu.match(/aid=(\d+)/)?.[1] || String(book.getVariable("aid"))
        if(aid){
             hotu = String(this.getReply(aid, 1, 3))
             newu = String(this.getReply(aid, 1, 2));
        }else{
            java.toast("详情页暂时无法加载评论\n请尝试进入视频后再查看评论")
        }
    }

