    }else{
        data = url;
    }

    let count = data?.cursor?.all_count;

    if(count)
    $("#statTotal span").textContent = count??0;

    upmid = data?.upper?.mid ?? upmid;
    if(data && data.root && modalPage ==1){
            data.top_replies = [];
            data.root.rcount = 0;
            modalTotalPage = data.page.count;
            data.top_replies.push(data.root)
      }

     commentListData = data.top_replies?data.top_replies.concat(data.replies):
     data.replies;
     if(!t){
         next_offset = data.cursor.pagination_reply.next_offset;
     }else if(t==1 && /^http/.test(url)){
         modalTotalPage = Math.ceil(data.page.count/20);
     }

    for(i in commentListData){
        let x = commentListData[i];
        let comment = {};
        comment.id = x.rpid;
        comment.reader_id = x.member.mid;
        comment.nickname = x.member.uname;

        comment.comment_body = parseContent(x.content.message,x.content.emote,x.content.at_name_to_mid,x.content.jump_url);

        comment.red = x.reply_control.up_reply?"UP主回复":"";
        comment.purple = comment.reader_id == upmid?"UP主":"";
