        comment.blue = x.reply_control.is_up_top?"置顶":"";
        comment.orange = "LV"+x.member.level_info.current_level;
        comment.green = x.reply_control.up_like?"UP主点赞":"";

        comment.meta_left = [formatDateText(x.reply_control.time_desc),(x.reply_control.location??"").replace(/IP属地：/,'')];
        comment.meta_right = [(x.like?'<i class="far fa-thumbs-up"></i>'+x.like:"")];


        comment.image_grid = x.content.pictures?x.content.pictures.map(x=>x.img_src):[];
        comment.replyNum = Number(x.rcount) ?? 0;
        if(x.replies && x.replies.length>0){
            comment.replyList = createJson(x,1,upmid)
        }
        commentList.push(comment)
    }
    return commentList
}
